const POPULAR_IDS = new Set(POPULAR_LANGUAGES.map(l => l.id))

/** Given a renderer registry, derive the full language lists. */
function buildLanguageLists(registry?: RendererRegistry): {
  popular: LanguageEntry[]
  rendererPlugins: LanguageEntry[]
  all: LanguageEntry[]
  rendererLangIds: Set<string>
} {
  const rendererLangIds = registry
    ? new Set(Object.keys(registry.versions))
    : new Set<string>()
  const rendererPlugins: LanguageEntry[] = registry
    ? Object.keys(registry.versions).sort().map((id) => ({
        id,
        label: id.charAt(0).toUpperCase() + id.slice(1),
        aliases: [],
      }))
    : []
  const all: LanguageEntry[] = [
    ...POPULAR_LANGUAGES,
    ...BASE_OTHER_LANGUAGES,
    ...rendererPlugins,
  ].sort((a, b) => a.label.localeCompare(b.label))
  return { popular: POPULAR_LANGUAGES, rendererPlugins, all, rendererLangIds }
}

function findLanguageLabel(langId: string, all: LanguageEntry[]): string {
  if (!langId) return 'text'
  const entry = all.find(
    l => l.id === langId || l.aliases.includes(langId),
  )
  return entry ? entry.label : langId
}

// ── Auto-detect language via highlight.js ─────────

let hljsAutoDetect: ((code: string) => string | null) | null = null

async function getAutoDetect(): Promise<(code: string) => string | null> {
  if (hljsAutoDetect) return hljsAutoDetect
  try {
    const hljs = (await import('highlight.js/lib/core')).default
    hljsAutoDetect = (code: string) => {
      if (!code.trim() || code.length < 10) return null
      try {
        const result = hljs.highlightAuto(code)
        if (result.language && result.relevance > 5) {
          return result.language
        }
      } catch { /* ignore */ }
      return null
    }
  } catch {
    hljsAutoDetect = () => null
  }
  return hljsAutoDetect
}

// ── Language Picker ───────────────────────────────

function createLanguagePicker(
  container: HTMLElement,
  anchor: HTMLElement,
  currentLang: string,
  codeContent: string,
  langLists: ReturnType<typeof buildLanguageLists>,
  onSelect: (lang: string) => void,
  onDismiss?: () => void,
): { destroy: () => void } {
  const { popular, rendererPlugins, all } = langLists

  const picker = document.createElement('div')
  picker.className = 'code-lang-picker'
  picker.setAttribute('contenteditable', 'false')
  picker.addEventListener('mousedown', (e) => { e.stopPropagation() })
  picker.addEventListener('click', (e) => { e.stopPropagation() })

  const searchWrap = document.createElement('div')
  searchWrap.className = 'code-lang-search'
  const searchInput = document.createElement('input')
  searchInput.type = 'text'
  searchInput.className = 'code-lang-search-input'
  searchInput.placeholder = 'Search language...'
  searchInput.autocomplete = 'off'
  searchInput.setAttribute('autocorrect', 'off')
  searchInput.setAttribute('autocapitalize', 'off')
  searchInput.spellcheck = false
  searchWrap.appendChild(searchInput)
  picker.appendChild(searchWrap)

  const listEl = document.createElement('div')
  listEl.className = 'code-lang-list'
  picker.appendChild(listEl)

  let detectedLang: string | null = null

  function renderList(filter: string) {
    listEl.innerHTML = ''
    const lowerFilter = filter.toLowerCase()

    const matchesFilter = (entry: LanguageEntry) => {
      if (!lowerFilter) return true
      return (
        entry.id.includes(lowerFilter) ||
        entry.label.toLowerCase().includes(lowerFilter) ||
        entry.aliases.some(a => a.includes(lowerFilter))
      )
    }

    if (detectedLang && !lowerFilter && detectedLang !== currentLang) {
      const label = findLanguageLabel(detectedLang, all)
      const suggestEl = document.createElement('div')
      suggestEl.className = 'code-lang-suggestion'
      suggestEl.innerHTML = `<span class="suggestion-icon">✦</span> ${label} <span class="suggestion-hint">detected</span>`
      suggestEl.addEventListener('mousedown', (e) => {
        e.preventDefault()
        e.stopPropagation()
        onSelect(detectedLang!)
        destroy()
      })
      listEl.appendChild(suggestEl)

      const divider = document.createElement('div')
      divider.className = 'code-lang-divider'
      listEl.appendChild(divider)
    }

    const popularMatches = popular.filter(matchesFilter)
    if (popularMatches.length > 0 && !lowerFilter) {
      const groupLabel = document.createElement('div')
      groupLabel.className = 'code-lang-group-label'
      groupLabel.textContent = 'Popular'
      listEl.appendChild(groupLabel)

      for (const lang of popularMatches) {
        listEl.appendChild(createOption(lang))
      }

      const rendererIds = new Set(rendererPlugins.map(l => l.id))
      const others = all.filter(
        l => !POPULAR_IDS.has(l.id) && !rendererIds.has(l.id) && matchesFilter(l),
      )
      if (others.length > 0) {
        const divider = document.createElement('div')
        divider.className = 'code-lang-divider'
        listEl.appendChild(divider)

        const allLabel = document.createElement('div')
        allLabel.className = 'code-lang-group-label'
        allLabel.textContent = 'All'
        listEl.appendChild(allLabel)
        for (const lang of others) {
          listEl.appendChild(createOption(lang))
        }
      }

      const rendererMatches = rendererPlugins.filter(matchesFilter)
      if (rendererMatches.length > 0) {
        const divider2 = document.createElement('div')
        divider2.className = 'code-lang-divider'
        listEl.appendChild(divider2)

        const rendererLabel = document.createElement('div')
        rendererLabel.className = 'code-lang-group-label'
        rendererLabel.textContent = 'Renderer Plugins'
        listEl.appendChild(rendererLabel)
        for (const lang of rendererMatches) {
          listEl.appendChild(createOption(lang))
        }
      }
    } else {
      const matches = all.filter(matchesFilter)
      for (const lang of matches) {
        listEl.appendChild(createOption(lang))
      }
      if (matches.length === 0) {
        const empty = document.createElement('div')
        empty.className = 'code-lang-empty'
        empty.textContent = 'No matches'
        listEl.appendChild(empty)
      }
    }
  }

  function createOption(lang: LanguageEntry): HTMLElement {
    const option = document.createElement('div')
    option.className = 'code-lang-option'
    if (lang.id === currentLang) option.classList.add('selected')
    option.textContent = lang.label
    option.addEventListener('mousedown', (e) => {
      e.preventDefault()
      e.stopPropagation()
      onSelect(lang.id)
      destroy()
    })
    return option
  }

  renderList('')

  searchInput.addEventListener('input', () => {
    renderList(searchInput.value)
  })

  searchInput.addEventListener('keydown', (e) => {
    e.stopPropagation()
    if (e.key === 'Escape') {
      destroy()
    }
  })

  // Append OUTSIDE ProseMirror's DOM tree so the editor's domObserver won't
  // detect focus moving to the search input and steal it back.
  const pickerHost = container.closest('.editor-wrapper') ?? document.body
  pickerHost.appendChild(picker)

  ;(function positionPicker() {
    const rect = anchor.getBoundingClientRect()
    picker.style.position = 'fixed'
    picker.style.top = `${rect.bottom + 2}px`
    picker.style.left = `${rect.left}px`
  })()

  requestAnimationFrame(() => searchInput.focus())

  getAutoDetect().then(detect => {
    detectedLang = detect(codeContent)
    if (detectedLang && !searchInput.value) {
      renderList('')
    }
  })

  function handleOutsideClick(e: MouseEvent) {
    if (!picker.contains(e.target as Node) && !anchor.contains(e.target as Node)) {
      destroy()
    }
  }

  function handleKeydown(e: KeyboardEvent) {
    if (e.key === 'Escape') {
      destroy()
    }
  }

  setTimeout(() => {
    document.addEventListener('mousedown', handleOutsideClick)
    document.addEventListener('keydown', handleKeydown, true)
  }, 0)

  function destroy() {
    document.removeEventListener('mousedown', handleOutsideClick)
    document.removeEventListener('keydown', handleKeydown, true)
    picker.remove()
    onDismiss?.()
  }

  return { destroy }
}

// ── Text escape helper ────────────────────────────

function escapeText(str: string): string {
  const d = document.createElement('div')
  d.textContent = str
  return d.innerHTML
}

// ── Copy button helper ────────────────────────────

function markCopied(btn: HTMLButtonElement) {
  btn.classList.add('copied')
  btn.title = 'Copied!'
  setTimeout(() => {
    btn.classList.remove('copied')
    btn.title = 'Copy'
  }, 1500)
}

function handleCopy(btn: HTMLButtonElement, codeEl: HTMLElement) {
  const text = codeEl.textContent || ''
  navigator.clipboard.writeText(text).then(() => markCopied(btn))
}

/** Resolve a solid background for the PNG: the preview's own bg, or white when transparent. */
function resolveBackground(el: HTMLElement): string {
  const bg = getComputedStyle(el).backgroundColor
  if (!bg || bg === 'transparent' || /rgba?\(\s*0\s*,\s*0\s*,\s*0\s*,\s*0\s*\)/.test(bg)) {
    return '#ffffff'
  }
  return bg
}

/** Rasterize an <svg> to a PNG Blob at 2x scale on a solid background. */
async function svgToPngBlob(svg: SVGSVGElement, background: string, originalSize?: { width: number; height: number }): Promise<Blob> {
  const scale = 2
  let w = 0
  let h = 0
  const vb = svg.viewBox?.baseVal
  if (vb && vb.width > 0 && vb.height > 0) {
    w = vb.width
    h = vb.height
  } else {
    const rect = originalSize ?? svg.getBoundingClientRect()
    w = rect.width
    h = rect.height
  }
  if (!(w > 0 && h > 0)) throw new Error('svg has no measurable size')

  const clone = svg.cloneNode(true) as SVGSVGElement
  if (!clone.getAttribute('xmlns')) clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg')
  const svgStr = new XMLSerializer().serializeToString(clone)
  const src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svgStr)

  const img = new Image()
  await new Promise<void>((resolve, reject) => {
    img.onload = () => resolve()
    img.onerror = () => reject(new Error('svg image load failed'))
    img.src = src
  })

  const canvas = document.createElement('canvas')
  canvas.width = Math.max(1, Math.round(w * scale))
  canvas.height = Math.max(1, Math.round(h * scale))
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('no 2d context')
  ctx.scale(scale, scale)
  ctx.fillStyle = background
  ctx.fillRect(0, 0, w, h)
  ctx.drawImage(img, 0, 0, w, h)

  return await new Promise<Blob>((resolve, reject) => {
    canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error('toBlob returned null'))), 'image/png')
  })
}

/**
 * Copy the rendered SVG inside `preview` to the clipboard as a PNG image.
 * Falls back to copying `codeEl` text when there is no SVG, the clipboard
 * image API is unavailable, or rasterization/write fails (e.g. foreignObject).
 */
function copyPreviewAsImage(btn: HTMLButtonElement, preview: HTMLElement, codeEl: HTMLElement, controller?: DiagramController) {
  const svg = preview.querySelector('svg') as SVGSVGElement | null
  const canWriteImage =
    typeof ClipboardItem !== 'undefined' &&
    !!navigator.clipboard &&
    typeof navigator.clipboard.write === 'function'
  if (!svg || !canWriteImage) {
    handleCopy(btn, codeEl)
    return
  }
  // Build the ClipboardItem synchronously inside the user-gesture handler,
  // deferring the async rasterization via a Promise (WebKit/Safari requirement).
  const blobPromise = svgToPngBlob(svg, resolveBackground(preview), controller?.originalSize(svg))
  navigator.clipboard
    .write([new ClipboardItem({ 'image/png': blobPromise })])
    .then(() => markCopied(btn))
    .catch(() => handleCopy(btn, codeEl))
}

// ── NodeView Factory ──────────────────────────────

export interface CodeBlockNodeViewOptions {
  diagramInteraction?: DiagramInteractionOptions
  mermaidLoader?: MermaidLoader
  rendererRegistry?: RendererRegistry
}

/**
 * NodeView factory builder. Returns the function to pass as
 * `nodeViews: { code_block: <returned> }` in EditorView config.
 *
 * Closes over a `RendererRegistry` so dispatched renderer plugins are
 * looked up via the consumer's injected registry rather than a Moraya-only
 * static map.
 */
export function createCodeBlockNodeViewFactory(opts: CodeBlockNodeViewOptions = {}) {
  const { rendererRegistry, mermaidLoader, diagramInteraction } = opts
  const labels = { ...diagramLabels, ...(typeof diagramInteraction === 'object' ? diagramInteraction.labels : {}) }
  const langLists = buildLanguageLists(rendererRegistry)
  const { rendererLangIds, all: allLanguages } = langLists

  return function createCodeBlockNodeView(
    nodeArg: PmNode,
    view: EditorView,
    getPos: () => number | undefined,
  ) {
    let node = nodeArg
    // ── DOM structure ──
    const wrapper = document.createElement('div')
    wrapper.className = 'code-block-wrapper'

    const toolbar = document.createElement('div')
    toolbar.className = 'code-block-toolbar'
    toolbar.setAttribute('contenteditable', 'false')

    const langLabel = document.createElement('span')
    langLabel.className = 'code-lang-label'
    langLabel.textContent = findLanguageLabel((node.attrs.language as string) || '', allLanguages)
    langLabel.title = 'Change language'

    const toggleBtn = document.createElement('button')
    toggleBtn.className = 'mermaid-toggle-btn'
    toggleBtn.type = 'button'

    const copyBtn = document.createElement('button')
    copyBtn.className = 'code-copy-btn'
    copyBtn.title = diagramInteraction ? labels.copy : 'Copy'
    copyBtn.setAttribute('aria-label', copyBtn.title)
    copyBtn.type = 'button'
    copyBtn.innerHTML =
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
      '<rect x="9" y="9" width="13" height="13" rx="2" ry="2"/>' +
      '<path d="M5 15H4a2 2 0 01-2-2V4a2 2 0 012-2h9a2 2 0 012 2v1"/>' +
      '</svg>' +
      '<svg class="check-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">' +
      '<path d="M20 6L9 17l-5-5"/>' +
      '</svg>'

    const toolbarRight = document.createElement('div')
    toolbarRight.className = 'code-toolbar-right'
    toolbarRight.appendChild(toggleBtn)
    toolbarRight.appendChild(copyBtn)

    toolbar.appendChild(langLabel)
    toolbar.appendChild(toolbarRight)

    const pre = document.createElement('pre')
    pre.className = 'code-block-pre'
    const code = document.createElement('code')
    code.className = 'code-block-code'
    pre.appendChild(code)

    const mermaidPreview = document.createElement('div')
    mermaidPreview.className = 'mermaid-preview'
    mermaidPreview.setAttribute('contenteditable', 'false')
    mermaidPreview.style.display = 'none'

    const rendererPreview = document.createElement('div')
    rendererPreview.className = 'renderer-preview'
    rendererPreview.setAttribute('contenteditable', 'false')
    rendererPreview.style.display = 'none'

    wrapper.appendChild(toolbar)
    wrapper.appendChild(pre)
    wrapper.appendChild(mermaidPreview)
    wrapper.appendChild(rendererPreview)

    // ── Mermaid state ──
    let isEditing = false
    let isMermaid = Boolean(mermaidLoader) && node.attrs.language === 'mermaid'
    let loadedApi: MermaidApi | undefined
    let destroyed = false, renderGeneration = 0
    let resizeObserver: ResizeObserver | undefined
    let contentWidth = 0
    let lastRenderedCode = ''
    let renderTimer: ReturnType<typeof setTimeout> | null = null

    // ── Renderer plugin state ──
    let isRenderer = node.attrs.language !== 'mermaid' && rendererLangIds.has((node.attrs.language as string) || '')
    let rendererEditing = false
    let lastRendererCode = ''
    let rendererTimer: ReturnType<typeof setTimeout> | null = null
    /** Last successfully loaded renderer module — kept so destroy() can be called. */
    let currentRendererModule: RendererPluginModule | null = null
    let currentRendererContainer: HTMLElement | null = null
    let rendererGeneration = 0
    type PendingRenderer = { output: HTMLElement; staging: HTMLElement; module?: RendererPluginModule; started: boolean; disposed: boolean; finalized: boolean }
    const pendingRenderers = new Set<PendingRenderer>()
    function disposePendingRenderer(pending: PendingRenderer, settled = false) {
      // Cancellation cannot abort arbitrary renderer Promises. Free existing resources now,
      // then sweep this same isolated output once more when late async work settles.
      if (pending.finalized || (pending.disposed && !settled)) return
      pending.disposed = true
      pending.finalized = settled
      if (pending.started) { try { pending.module?.destroy?.(pending.output) } catch {} }
      pending.staging.remove(); pendingRenderers.delete(pending)
    }
    function disposePendingRenderers() { for (const pending of pendingRenderers) disposePendingRenderer(pending) }
    let diagram: DiagramController | undefined
    let focusPreviewAfterRender = false
    const canInteract = () => Boolean(diagramInteraction) && (isMermaid || ['dot', 'graphviz'].includes(String(node.attrs.language)))
    function clearDiagram() { diagram?.destroy(); diagram = undefined }
    function bindDiagram(preview: HTMLElement) {
      if (!canInteract() || destroyed || !preview.querySelector('svg')) return
      clearDiagram()
      const pos = getPos()
      if (pos === undefined) return
      diagram = createDiagramController({ preview, wrapper, toolbar, view, getPos,
        snapshot: diagramSnapshot(view, pos, node.textContent, String(node.attrs.language)), labels })
      if (focusPreviewAfterRender) {
        focusPreviewAfterRender = false
        if (document.activeElement === toggleBtn) preview.focus({ preventScroll: true })
      }
    }
    function focusCode() {
      const pos = getPos()
      if (view.editable && pos !== undefined) view.dispatch(view.state.tr.setSelection(TextSelection.create(view.state.doc, pos + 1)).setMeta('addToHistory', false))
      view.focus()
    }
    function disposeRenderer() {
      if (currentRendererContainer) {
        try { currentRendererModule?.destroy?.(currentRendererContainer) } catch { /* renderer cleanup is best effort */ }
      }
      currentRendererModule = null; currentRendererContainer = null
    }
    toolbar.addEventListener('focusin', () => {
      if (!diagram || !view.editable) return
      const pos = getPos()
      if (pos !== undefined) view.dispatch(view.state.tr.setSelection(TextSelection.create(view.state.doc, pos + 1)).setMeta('addToHistory', false))
    })

    function disconnectMermaidResize() {
      resizeObserver?.disconnect()
      resizeObserver = undefined
    }

    function observeMermaidWidth() {
      if (resizeObserver) return
      const style = getComputedStyle(wrapper)
      contentWidth = Math.max(0, wrapper.getBoundingClientRect().width
        - (parseFloat(style.paddingLeft) || 0) - (parseFloat(style.paddingRight) || 0)
        - (parseFloat(style.borderLeftWidth) || 0) - (parseFloat(style.borderRightWidth) || 0))
      if (typeof ResizeObserver === 'undefined') return
      resizeObserver = new ResizeObserver(entries => {
        if (destroyed || !isMermaid || isEditing) return
        const width = entries.find(entry => entry.target === wrapper)?.contentRect.width
        if (width === undefined || !Number.isFinite(width) || width <= 0 || width === contentWidth) return
        contentWidth = width
        lastRenderedCode = ''
        triggerMermaidRender()
      })
      resizeObserver.observe(wrapper)
    }

    function syncMermaidMode() {
      if (canInteract()) toolbar.dataset.diagramInteraction = ''; else delete toolbar.dataset.diagramInteraction
      const showPreview = isMermaid && !isEditing
      if (!showPreview) { clearDiagram(); disconnectMermaidResize() }
      pre.style.display = (showPreview || (isRenderer && !rendererEditing)) ? 'none' : ''
      mermaidPreview.style.display = showPreview ? (diagram ? 'block' : 'flex') : 'none'
      toggleBtn.style.display = (isMermaid || isRenderer) ? 'inline-flex' : 'none'
      wrapper.classList.toggle('mermaid-preview-mode', showPreview)
      if (isMermaid) {
        toggleBtn.textContent = diagramInteraction ? (isEditing ? labels.preview : labels.edit) : (isEditing ? '👁 Preview' : '✏️ Edit')
        if (showPreview) triggerMermaidRender()
      }
    }

    function failMermaid(message: string) {
      clearDiagram()
      disconnectMermaidResize()
      lastRenderedCode = ''
      isEditing = true
      pre.style.display = ''
      wrapper.classList.remove('mermaid-preview-mode')
      toggleBtn.textContent = diagramInteraction ? labels.preview : '👁 Preview'
      mermaidPreview.style.display = 'flex'
      mermaidPreview.innerHTML = `<div class="mermaid-error">${escapeText(message)}</div>`
    }
    function triggerMermaidRender() {
      if (destroyed || !isMermaid || !mermaidLoader) return
      const codeText = node.textContent
      if (codeText === lastRenderedCode && codeText.trim()) return
      const generation = ++renderGeneration
      if (renderTimer) clearTimeout(renderTimer)
      if (!codeText.trim()) {
        clearDiagram()
        mermaidPreview.innerHTML = '<div class="mermaid-empty">Empty diagram</div>'
        lastRenderedCode = ''
        return
      }
      lastRenderedCode = codeText
      const valid = () => !destroyed && isMermaid && !isEditing && generation === renderGeneration && node.textContent === codeText
      renderTimer = setTimeout(async () => {
        if (!valid()) return
        clearDiagram()
        mermaidPreview.innerHTML = '<div class="mermaid-loading"><div class="mermaid-spinner"></div>Loading diagram...</div>'
        try {
          const api = await loadMermaidApi(mermaidLoader)
          if (!valid()) return
          loadedApi = api
          const responsive = 'supportsResponsiveLayout' in api && api.supportsResponsiveLayout
          if (responsive) {
            observeMermaidWidth()
            if (!Number.isFinite(contentWidth) || contentWidth <= 0) {
              lastRenderedCode = ''
              return
            }
          }
          const result = responsive
            ? await api.renderMermaid(codeText, { maxWidth: contentWidth, container: mermaidPreview })
            : await api.renderMermaid(codeText)
          if (!valid()) return
          if ('svg' in result) { mermaidPreview.innerHTML = result.svg; bindDiagram(mermaidPreview) }
          else failMermaid(result.error)
        } catch {
          if (valid()) failMermaid('Render failed — try Preview again')
        }
      }, 150)
    }

    // ── Renderer plugin sync ──
    function syncRendererMode() {
      if (canInteract()) toolbar.dataset.diagramInteraction = ''; else delete toolbar.dataset.diagramInteraction
      const showPreview = isRenderer && !rendererEditing
      if (!showPreview) clearDiagram()
      pre.style.display = (showPreview || (isMermaid && !isEditing)) ? 'none' : ''
      rendererPreview.style.display = showPreview ? 'block' : 'none'
      toggleBtn.style.display = (isMermaid || isRenderer) ? 'inline-flex' : 'none'
      wrapper.classList.toggle('renderer-preview-mode', showPreview)
      if (isRenderer) {
        toggleBtn.textContent = diagramInteraction ? (rendererEditing ? labels.preview : labels.edit) : (rendererEditing ? '👁 Preview' : '✏️ Edit')
        if (showPreview) triggerRendererRender()
      }
    }

    function triggerRendererRender() {
      const source = node.textContent
      const lang = (node.attrs.language as string) || ''
      if (destroyed || rendererEditing || !rendererRegistry || !rendererRegistry.has(lang)) return
      if (source === lastRendererCode && source.trim()) {
        if (!diagram && currentRendererContainer) bindDiagram(rendererPreview)
        return
      }
      const generation = ++rendererGeneration
      disposePendingRenderers()
      if (rendererTimer) clearTimeout(rendererTimer)
      if (!source.trim()) {
        clearDiagram(); disposeRenderer()
        rendererPreview.innerHTML = '<div class="renderer-empty">Empty block</div>'
        lastRendererCode = ''
        return
      }
      lastRendererCode = source
      const valid = () => !destroyed && !rendererEditing && isRenderer && generation === rendererGeneration && node.attrs.language === lang && node.textContent === source
      rendererTimer = setTimeout(async () => {
        if (!valid()) return
        clearDiagram(); disposeRenderer()
        rendererPreview.innerHTML = '<div class="renderer-loading"><div class="renderer-spinner"></div>Rendering...</div>'
        let module: RendererPluginModule | undefined
        const staging = document.createElement('div')
        const output = document.createElement('div')
        staging.appendChild(output)
        const pending: PendingRenderer = { output, staging, started: false, disposed: false, finalized: false }
        pendingRenderers.add(pending)
        output.className = 'renderer-content'
        try {
          module = await rendererRegistry.load(lang)
          if (!valid() || pending.disposed) { disposePendingRenderer(pending, true); return }
          pending.module = module
          // A connected but isolated staging container gives layout-dependent renderers real width.
          // Stale async work only ever writes to its own output, never the current preview.
          Object.assign(staging.style, { position: 'absolute', left: '0', top: '0', visibility: 'hidden', pointerEvents: 'none', width: `${rendererPreview.clientWidth || wrapper.clientWidth}px` })
          wrapper.appendChild(staging)
          pending.started = true
          await module.render(source, output)
          if (!valid() || pending.disposed) { disposePendingRenderer(pending, true); return }
          pendingRenderers.delete(pending)
          rendererPreview.replaceChildren(output)
          staging.remove()
          currentRendererModule = module; currentRendererContainer = output
          bindDiagram(rendererPreview)
        } catch (e) {
          disposePendingRenderer(pending, true)
          if (!valid()) return
          lastRendererCode = ''
          rendererPreview.innerHTML =
            `<div class="renderer-error" data-language="${escapeText(lang)}" data-error="${escapeText(String(e))}">[Renderer ${escapeText(lang)} failed]</div>`
        }
      }, 150)
    }

    function onThemeChange() {
      if (destroyed) return
      loadedApi?.updateMermaidTheme()
      if (isMermaid && !isEditing) {
        lastRenderedCode = ''
        triggerMermaidRender()
      }
    }

    if (isMermaid) {
      installThemeObserver()
      mermaidReRenderCallbacks.add(onThemeChange)
      // Defer: ProseMirror populates contentDOM AFTER NodeView factory returns
      requestAnimationFrame(() => { if (!destroyed) syncMermaidMode() })
    } else if (isRenderer) {
      // Hide pre and show toggle button immediately, then re-trigger after content arrives
      syncRendererMode()
      requestAnimationFrame(() => { if (!destroyed) syncRendererMode() })
    } else {
      syncMermaidMode()
    }

    // ── Language picker ──
    let activePicker: { destroy: () => void } | null = null

    langLabel.addEventListener('mousedown', (e) => {
      if (!view.editable) return
      e.preventDefault()
      e.stopPropagation()

      if (activePicker) {
        activePicker.destroy()
        activePicker = null
        wrapper.classList.remove('picker-open')
        return
      }

      const currentLang = (node.attrs.language as string) || ''
      const codeContent = code.textContent || ''
      wrapper.classList.add('picker-open')
      activePicker = createLanguagePicker(
        wrapper,
        langLabel,
        currentLang,
        codeContent,
        langLists,
        (newLang) => {
          activePicker = null
          wrapper.classList.remove('picker-open')
          const pos = getPos()
          if (pos === undefined) return
          view.dispatch(
            view.state.tr.setNodeMarkup(pos, undefined, {
              ...node.attrs,
              language: newLang,
            }),
          )
          view.focus()
        },
        () => {
          activePicker = null
          wrapper.classList.remove('picker-open')
        },
      )
    })

    // ── Mermaid / Renderer toggle button ──
    toggleBtn.addEventListener('mousedown', e => e.preventDefault())
    toggleBtn.addEventListener(diagramInteraction ? 'click' : 'mousedown', (e) => {
      e.preventDefault()
      e.stopPropagation()
      if (isMermaid) {
        isEditing = !isEditing
        focusPreviewAfterRender = Boolean(diagramInteraction) && !isEditing
        if (focusPreviewAfterRender) toggleBtn.focus({ preventScroll: true })
        if (isEditing) { renderGeneration++; lastRenderedCode = '' }
        syncMermaidMode()
      } else if (isRenderer) {
        rendererEditing = !rendererEditing
        focusPreviewAfterRender = Boolean(diagramInteraction) && !rendererEditing
        if (focusPreviewAfterRender) toggleBtn.focus({ preventScroll: true })
        if (rendererEditing) { rendererGeneration++; disposePendingRenderers(); if (!currentRendererContainer) lastRendererCode = '' }
        syncRendererMode()
      }
      if (isEditing || rendererEditing) { if (diagramInteraction) focusCode(); else view.focus() }
    })

    // Click SVG preview → enter edit mode
    mermaidPreview.addEventListener('mousedown', (e) => {
      if (canInteract()) return
      e.preventDefault()
      e.stopPropagation()
      isEditing = true
      renderGeneration++; lastRenderedCode = ''
      syncMermaidMode()
      view.focus()
    })

    // ── Copy button ──
    // In a rendered preview (mermaid / renderer SVG) copy the image as PNG;
    // in edit mode or a plain code block copy the source text.
    copyBtn.addEventListener('mousedown', e => e.preventDefault())
    copyBtn.addEventListener(diagramInteraction ? 'click' : 'mousedown', (e) => {
      e.preventDefault()
      e.stopPropagation()
      if (isMermaid && !isEditing) {
        copyPreviewAsImage(copyBtn, mermaidPreview, code, diagram)
      } else if (isRenderer && !rendererEditing) {
        copyPreviewAsImage(copyBtn, rendererPreview, code, diagram)
      } else {
        handleCopy(copyBtn, code)
      }
    })

    return {
      dom: wrapper,
      contentDOM: code,

      stopEvent(event: Event) {
        const target = event.target as Node
        return !code.contains(target) && wrapper.contains(target) && target !== code
      },

      ignoreMutation(mutation: { target: Node }) {
        return !code.contains(mutation.target)
      },

      update(updatedNode: PmNode) {
        if (updatedNode.type.name !== 'code_block') return false
        const languageChanged = node.attrs.language !== updatedNode.attrs.language
        const sourceChanged = node.textContent !== updatedNode.textContent
        if (languageChanged || sourceChanged) { clearDiagram(); rendererGeneration++; disposePendingRenderers(); renderGeneration++; lastRendererCode = ''; lastRenderedCode = '' }
        node = updatedNode
        langLabel.textContent = findLanguageLabel((updatedNode.attrs.language as string) || '', allLanguages)

        const wasMermaid = isMermaid
        isMermaid = Boolean(mermaidLoader) && updatedNode.attrs.language === 'mermaid'
        if (isMermaid !== wasMermaid) {
          renderGeneration++; lastRenderedCode = ''
          disconnectMermaidResize()
          isEditing = false
          if (isMermaid) {
            installThemeObserver()
            mermaidReRenderCallbacks.add(onThemeChange)
          } else {
            mermaidReRenderCallbacks.delete(onThemeChange)
          }
        }

        const wasRenderer = isRenderer
        isRenderer = updatedNode.attrs.language !== 'mermaid' && rendererLangIds.has((updatedNode.attrs.language as string) || '')
        if (isRenderer !== wasRenderer || languageChanged) {
          rendererEditing = false
          lastRendererCode = ''
          rendererPreview.innerHTML = ''
          disposeRenderer()
        }

        if (isRenderer) {
          syncRendererMode()
        } else {
          rendererPreview.style.display = 'none'
          wrapper.classList.remove('renderer-preview-mode')
          syncMermaidMode()
        }
        return true
      },

      selectNode() {
        wrapper.classList.add('ProseMirror-selectednode')
      },

      deselectNode() {
        wrapper.classList.remove('ProseMirror-selectednode')
      },

      destroy() {
        destroyed = true; renderGeneration++; rendererGeneration++
        disposePendingRenderers()
        clearDiagram()
        disconnectMermaidResize()
        if (activePicker) {
          activePicker.destroy()
          activePicker = null
        }
        if (renderTimer) clearTimeout(renderTimer)
        if (rendererTimer) clearTimeout(rendererTimer)
        disposeRenderer()
        mermaidReRenderCallbacks.delete(onThemeChange)
      },
    }
  }
}
